// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title RaceLeaderboard
 * @notice Stores verified on-chain race results and best times per player per track on Monad Testnet.
 * @dev Access controlled via OpenZeppelin AccessControl. Results can only be submitted by addresses
 *      holding the grantable/revocable REPORTER_ROLE.
 */
contract RaceLeaderboard is AccessControl {
    bytes32 public constant REPORTER_ROLE = keccak256("REPORTER_ROLE");

    struct TrackRecord {
        address player;
        uint256 timeMs;
        uint256 timestamp;
    }

    // Mapping: trackId => player address => best lap time in milliseconds
    mapping(bytes32 => mapping(address => uint256)) public playerBestTime;

    // Mapping: trackId => ordered array of top records (fastest first)
    mapping(bytes32 => TrackRecord[]) internal _topTimes;

    // Maximum number of stored top leaderboard records per track
    uint256 public constant MAX_LEADERBOARD_ENTRIES = 50;

    event ResultSubmitted(
        bytes32 indexed trackId,
        address indexed player,
        uint256 timeMs,
        bool isNewPersonalBest,
        uint256 timestamp
    );

    event TrackRecordBroken(
        bytes32 indexed trackId,
        address indexed player,
        uint256 newRecordTimeMs
    );

    /**
     * @notice Initializes the contract and grants DEFAULT_ADMIN_ROLE and REPORTER_ROLE to deployer.
     * @param admin Initial administrator address.
     * @param initialReporter Initial authorized reporter address (can be updated dynamically).
     */
    constructor(address admin, address initialReporter) {
        require(admin != address(0), "Invalid admin address");
        require(initialReporter != address(0), "Invalid reporter address");

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(REPORTER_ROLE, initialReporter);
    }

    /**
     * @notice Submits a race time for a player on a specific track.
     * @dev Restricted to the REPORTER_ROLE. Only updates storage if the time beats
     *      the player's previous best for that trackId.
     * @param trackId bytes32 hash of the track identifier (e.g. keccak256("neon_city")).
     * @param player Address of the racer.
     * @param timeMs Finish / lap time in milliseconds.
     * @return isNewPersonalBest True if this result updated the player's personal best.
     */
    function submitResult(
        bytes32 trackId,
        address player,
        uint256 timeMs
    ) external onlyRole(REPORTER_ROLE) returns (bool isNewPersonalBest) {
        require(player != address(0), "Invalid player address");
        require(timeMs > 0, "Time must be greater than zero");

        uint256 currentBest = playerBestTime[trackId][player];

        // Only update storage if this is the player's first run or beats their previous best
        if (currentBest == 0 || timeMs < currentBest) {
            playerBestTime[trackId][player] = timeMs;
            isNewPersonalBest = true;

            _insertTopTime(trackId, player, timeMs);

            emit ResultSubmitted(trackId, player, timeMs, true, block.timestamp);
        } else {
            emit ResultSubmitted(trackId, player, timeMs, false, block.timestamp);
        }

        return isNewPersonalBest;
    }

    /**
     * @notice Returns the personal best time for a specific player on a track.
     * @param trackId bytes32 hash of the track identifier.
     * @param player Address of the racer.
     * @return timeMs Best time in milliseconds (0 if no recorded time).
     */
    function getPlayerBest(
        bytes32 trackId,
        address player
    ) external view returns (uint256 timeMs) {
        return playerBestTime[trackId][player];
    }

    /**
     * @notice Returns the top leaderboard records for a track (fastest first).
     * @param trackId bytes32 hash of the track identifier.
     * @param count Maximum number of records to return.
     * @return records Array of TrackRecord sorted by ascending timeMs.
     */
    function getTopTimes(
        bytes32 trackId,
        uint256 count
    ) external view returns (TrackRecord[] memory records) {
        TrackRecord[] storage list = _topTimes[trackId];
        uint256 total = list.length;
        uint256 returnCount = count < total ? count : total;

        records = new TrackRecord[](returnCount);
        for (uint256 i = 0; i < returnCount; i++) {
            records[i] = list[i];
        }
        return records;
    }

    /**
     * @notice Total number of leaderboard records stored for a track.
     */
    function getTrackRecordCount(bytes32 trackId) external view returns (uint256) {
        return _topTimes[trackId].length;
    }

    /**
     * @dev Internal helper to insert/update and sort a record in the top times list.
     */
    function _insertTopTime(bytes32 trackId, address player, uint256 timeMs) internal {
        TrackRecord[] storage list = _topTimes[trackId];

        // Check if player already exists in the top list and remove older entry
        int256 existingIdx = -1;
        for (uint256 i = 0; i < list.length; i++) {
            if (list[i].player == player) {
                existingIdx = int256(i);
                break;
            }
        }

        if (existingIdx >= 0) {
            // Remove existing record to re-insert at updated sorted position
            for (uint256 j = uint256(existingIdx); j < list.length - 1; j++) {
                list[j] = list[j + 1];
            }
            list.pop();
        }

        // Insert in ascending order of timeMs (fastest first)
        uint256 insertPos = list.length;
        for (uint256 k = 0; k < list.length; k++) {
            if (timeMs < list[k].timeMs) {
                insertPos = k;
                break;
            }
        }

        if (insertPos < MAX_LEADERBOARD_ENTRIES) {
            list.push(TrackRecord({ player: address(0), timeMs: 0, timestamp: 0 }));
            for (uint256 m = list.length - 1; m > insertPos; m--) {
                list[m] = list[m - 1];
            }
            list[insertPos] = TrackRecord({
                player: player,
                timeMs: timeMs,
                timestamp: block.timestamp
            });

            if (list.length > MAX_LEADERBOARD_ENTRIES) {
                list.pop();
            }

            if (insertPos == 0) {
                emit TrackRecordBroken(trackId, player, timeMs);
            }
        }
    }
}

contracts/RaceWager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title RaceWager
 * @notice Escrow-based wagering between racers for multiplayer and tournament races on Monad Testnet.
 * @dev Employs OpenZeppelin AccessControl for match lifecycle authorization and ReentrancyGuard
 *      for all state transitions and native MON currency transfers.
 */
contract RaceWager is AccessControl, ReentrancyGuard {
    bytes32 public constant REPORTER_ROLE = keccak256("REPORTER_ROLE");

    enum MatchState {
        Open,      // Accepting deposits
        Locked,    // Race started / in progress; no deposits or standard withdrawals
        Settled,   // Match completed; winner paid out
        Cancelled  // Match cancelled; deposits refunded
    }

    struct Match {
        uint256 matchId;
        bytes32 trackId;
        uint256 wagerAmount;       // Wager amount in MON per racer
        uint256 totalPool;         // Total MON currently locked in escrow
        uint256 createdAt;
        uint256 lockedAt;
        uint256 settledAt;
        MatchState state;
        address[] requiredPlayers;
        address winner;
        uint256 depositedCount;
    }

    uint256 public nextMatchId = 1;

    // Timeout durations
    uint256 public constant LOCK_TIMEOUT = 15 minutes; // If locked > 15 mins with no report, racers can refund
    uint256 public constant OPEN_TIMEOUT = 1 hours;    // If open > 1 hr without all deposits, racers can refund

    // Mapping: matchId => Match data
    mapping(uint256 => Match) public matches;

    // Mapping: matchId => player => whether player has deposited
    mapping(uint256 => mapping(address => bool)) public hasDeposited;

    // Mapping: matchId => player => whether player is an authorized participant
    mapping(uint256 => mapping(address => bool)) public isParticipant;

    // Events
    event MatchCreated(
        uint256 indexed matchId,
        bytes32 indexed trackId,
        uint256 wagerAmount,
        address[] players,
        uint256 createdAt
    );

    event WagerDeposited(
        uint256 indexed matchId,
        address indexed player,
        uint256 amount,
        uint256 currentDepositedCount
    );

    event MatchLocked(
        uint256 indexed matchId,
        uint256 totalPool,
        uint256 lockedAt
    );

    event MatchSettled(
        uint256 indexed matchId,
        address indexed winner,
        uint256 payoutAmount,
        uint256 settledAt
    );

    event WagerRefunded(
        uint256 indexed matchId,
        address indexed player,
        uint256 amount
    );

    event MatchCancelled(
        uint256 indexed matchId,
        string reason
    );

    constructor(address admin, address initialReporter) {
        require(admin != address(0), "Invalid admin address");
        require(initialReporter != address(0), "Invalid reporter address");

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(REPORTER_ROLE, initialReporter);
    }

    /**
     * @notice Creates a new wager match for a specific track and list of participant addresses.
     * @param trackId bytes32 hash of the track identifier.
     * @param players List of racer addresses required to deposit.
     * @param wagerAmount Amount of native MON required from each racer.
     * @return matchId The created match unique identifier.
     */
    function createMatch(
        bytes32 trackId,
        address[] calldata players,
        uint256 wagerAmount
    ) external returns (uint256 matchId) {
        require(players.length >= 2, "Minimum 2 players required");
        require(players.length <= 12, "Maximum 12 players supported");
        require(wagerAmount > 0, "Wager amount must be greater than zero");

        matchId = nextMatchId++;
        Match storage m = matches[matchId];
        m.matchId = matchId;
        m.trackId = trackId;
        m.wagerAmount = wagerAmount;
        m.createdAt = block.timestamp;
        m.state = MatchState.Open;
        m.requiredPlayers = players;

        for (uint256 i = 0; i < players.length; i++) {
            address p = players[i];
            require(p != address(0), "Invalid player address");
            require(!isParticipant[matchId][p], "Duplicate player in match");
            isParticipant[matchId][p] = true;
        }

        emit MatchCreated(matchId, trackId, wagerAmount, players, block.timestamp);
        return matchId;
    }

    /**
     * @notice Racers deposit their exact wager in MON into match escrow.
     * @param matchId Identifier of the open match.
     */
    function depositWager(uint256 matchId) external payable nonReentrant {
        Match storage m = matches[matchId];
        require(m.state == MatchState.Open, "Match not accepting deposits");
        require(isParticipant[matchId][msg.sender], "Not a registered participant");
        require(!hasDeposited[matchId][msg.sender], "Wager already deposited");
        require(msg.value == m.wagerAmount, "Incorrect wager amount sent");

        hasDeposited[matchId][msg.sender] = true;
        m.depositedCount += 1;
        m.totalPool += msg.value;

        emit WagerDeposited(matchId, msg.sender, msg.value, m.depositedCount);
    }

    /**
     * @notice Locks the match once all racers have deposited.
     * @dev Restricted to the REPORTER_ROLE. Transitions state to Locked.
     * @param matchId Identifier of the match.
     */
    function lockMatch(uint256 matchId) external onlyRole(REPORTER_ROLE) {
        Match storage m = matches[matchId];
        require(m.state == MatchState.Open, "Match not in Open state");
        require(m.depositedCount == m.requiredPlayers.length, "Not all players deposited");

        m.state = MatchState.Locked;
        m.lockedAt = block.timestamp;

        emit MatchLocked(matchId, m.totalPool, block.timestamp);
    }

    /**
     * @notice Reports final race finish order and pays out escrow pool to the winner.
     * @dev Restricted to the REPORTER_ROLE. Winner takes 100% of the pool (no rake in v1).
     * @param matchId Identifier of the locked match.
     * @param rankedPlayers Ordered list of finishers (first element is the winner).
     */
    function reportResult(
        uint256 matchId,
        address[] calldata rankedPlayers
    ) external onlyRole(REPORTER_ROLE) nonReentrant {
        Match storage m = matches[matchId];
        require(m.state == MatchState.Locked, "Match is not locked");
        require(rankedPlayers.length > 0, "Empty finish results");

        address winner = rankedPlayers[0];
        require(isParticipant[matchId][winner], "Winner not a match participant");
        require(hasDeposited[matchId][winner], "Winner did not deposit wager");

        uint256 payoutAmount = m.totalPool;
        require(payoutAmount > 0, "No pool funds to payout");

        // Checks-Effects
        m.state = MatchState.Settled;
        m.winner = winner;
        m.settledAt = block.timestamp;
        m.totalPool = 0;

        // Future Payout Split Hook (stubbed for v2 multi-podium prize pools)
        // uint256[] memory split = _calculatePayoutSplit(payoutAmount, rankedPlayers.length);

        // Interaction (Transfer entire escrow pool to the winner)
        (bool success, ) = payable(winner).call{value: payoutAmount}("");
        require(success, "Payout transfer failed");

        emit MatchSettled(matchId, winner, payoutAmount, block.timestamp);
    }

    /**
     * @notice Allows any depositor to pull their wager back if match stalls past timeout.
     * @dev Prevents funds from being stuck if game crashes mid-race.
     * @param matchId Identifier of the match.
     */
    function claimRefund(uint256 matchId) external nonReentrant {
        Match storage m = matches[matchId];
        require(
            m.state == MatchState.Open || m.state == MatchState.Locked || m.state == MatchState.Cancelled,
            "Cannot refund in current state"
        );
        require(hasDeposited[matchId][msg.sender], "No active deposit found");

        if (m.state == MatchState.Locked) {
            require(block.timestamp >= m.lockedAt + LOCK_TIMEOUT, "Lock timeout not elapsed");
        } else if (m.state == MatchState.Open) {
            require(block.timestamp >= m.createdAt + OPEN_TIMEOUT, "Open timeout not elapsed");
        }

        uint256 refundAmount = m.wagerAmount;
        require(m.totalPool >= refundAmount, "Insufficient pool balance");

        // Checks-Effects
        hasDeposited[matchId][msg.sender] = false;
        m.depositedCount -= 1;
        m.totalPool -= refundAmount;

        if (m.totalPool == 0) {
            m.state = MatchState.Cancelled;
            emit MatchCancelled(matchId, "All deposits refunded");
        }

        // Interaction
        (bool success, ) = payable(msg.sender).call{value: refundAmount}("");
        require(success, "Refund transfer failed");

        emit WagerRefunded(matchId, msg.sender, refundAmount);
    }

    /**
     * @notice Emergency administrative cancellation to immediately allow player refunds.
     * @param matchId Identifier of the match.
     */
    function cancelMatch(uint256 matchId, string calldata reason) external onlyRole(REPORTER_ROLE) {
        Match storage m = matches[matchId];
        require(m.state == MatchState.Open || m.state == MatchState.Locked, "Cannot cancel match");

        m.state = MatchState.Cancelled;
        emit MatchCancelled(matchId, reason);
    }

    /**
     * @notice View helper to check match participant details.
     */
    function getMatchPlayers(uint256 matchId) external view returns (address[] memory) {
        return matches[matchId].requiredPlayers;
    }

    /**
     * @dev Future extension hook for multi-position prize distributions.
     */
    function _calculatePayoutSplit(uint256 totalAmount, uint256 playerCount) internal pure returns (uint256[] memory) {
        uint256[] memory splits = new uint256[](playerCount);
        splits[0] = totalAmount; // 100% to winner in v1
        return splits;
    }
}

contracts/SmashToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title SmashToken ($SMASH)
 * @notice ERC-20 Reward and In-Game Utility Token for Monad SmashKarts
 * @dev Optimized for Monad Testnet with testnet faucet, gameplay rewards, and garage burning
 */
contract SmashToken {
    string public name = "Monad Smash Token";
    string public symbol = "SMASH";
    uint8 public decimals = 18;
    uint256 public totalSupply;

    address public owner;
    address public rewardVault;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public lastFaucetClaim;

    uint256 public constant FAUCET_AMOUNT = 100 * 10**18; // 100 SMASH
    uint256 public constant FAUCET_COOLDOWN = 1 hours;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event RewardVaultUpdated(address indexed newVault);
    event FaucetClaimed(address indexed recipient, uint256 amount);
    event InGameBurn(address indexed burner, uint256 amount, string reason);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    modifier onlyAuthorized() {
        require(msg.sender == owner || msg.sender == rewardVault, "Not authorized to mint");
        _;
    }

    constructor() {
        owner = msg.sender;
        // Mint initial supply to owner for liquidity & reward pools
        _mint(msg.sender, 1_000_000 * 10**18);
    }

    function setRewardVault(address _rewardVault) external onlyOwner {
        rewardVault = _rewardVault;
        emit RewardVaultUpdated(_rewardVault);
    }

    function transfer(address to, uint256 value) external returns (bool) {
        require(to != address(0), "Invalid recipient");
        require(balanceOf[msg.sender] >= value, "Insufficient balance");
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        emit Transfer(msg.sender, to, value);
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        require(to != address(0), "Invalid recipient");
        require(balanceOf[from] >= value, "Insufficient balance");
        require(allowance[from][msg.sender] >= value, "Allowance exceeded");

        allowance[from][msg.sender] -= value;
        balanceOf[from] -= value;
        balanceOf[to] += value;
        emit Transfer(from, to, value);
        return true;
    }

    function mintReward(address recipient, uint256 amount) external onlyAuthorized returns (bool) {
        _mint(recipient, amount);
        return true;
    }

    function claimFaucet() external returns (bool) {
        require(block.timestamp - lastFaucetClaim[msg.sender] >= FAUCET_COOLDOWN, "Faucet cooldown active");
        lastFaucetClaim[msg.sender] = block.timestamp;
        _mint(msg.sender, FAUCET_AMOUNT);
        emit FaucetClaimed(msg.sender, FAUCET_AMOUNT);
        return true;
    }

    function burnForGarageItem(uint256 amount, string calldata itemId) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "Insufficient SMASH balance");
        balanceOf[msg.sender] -= amount;
        totalSupply -= amount;
        emit Transfer(msg.sender, address(0), amount);
        emit InGameBurn(msg.sender, amount, itemId);
        return true;
    }

    function _mint(address to, uint256 amount) internal {
        require(to != address(0), "Invalid address");
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }
}

